{
  "per_column": [
    {
      "name": "clinical_category",
      "analytical_usefulness": 0.97,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "Directly answers the query by categorizing the type of concern; samples map soundly (acne->dermatologic, cough->infectious, knee->musculoskeletal). Strong grouping axis."
    },
    {
      "name": "visit_purpose",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Distinguishes acute vs chronic vs wellness visits, a useful complementary axis. Mostly well grounded, though acne labeled chronic_disease_management is a defensible but slightly loose reading."
    },
    {
      "name": "problem_acuity",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.75,
      "hallucination_observed": false,
      "rationale": "Ordinal severity gives modelable leverage, but partly overlaps existing 'urgency' column. Values are plausible inferences from text, though the 1-5 scale is somewhat subjective/underspecified."
    },
    {
      "name": "chronicity",
      "analytical_usefulness": 0.88,
      "source_groundedness": 0.88,
      "hallucination_observed": false,
      "rationale": "New-onset vs chronic-stable is a genuine analytical axis for concern types. Sample reads are sound (viral URI new_onset, post-MI chronic_stable)."
    },
    {
      "name": "care_action_type",
      "analytical_usefulness": 0.82,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Captures the response/action, useful for characterizing visits. Grounded in text (adapalene->medication_initiation, MRI->diagnostic_workup). Slightly tangential to 'concern type' but adds leverage."
    },
    {
      "name": "body_system",
      "analytical_usefulness": 0.5,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Well grounded but substantially redundant with clinical_category (cardiovascular, musculoskeletal, skin largely mirror each other), reducing analytical novelty for this query."
    },
    {
      "name": "symptom_mechanism",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.82,
      "hallucination_observed": false,
      "rationale": "Pathophysiologic mechanism is a distinct, non-trivial axis. Sample reads reasonable (twisting injury->traumatic, post-MI->ischemic). Some inference risk but warranted."
    },
    {
      "name": "referral_or_escalation",
      "analytical_usefulness": 0.72,
      "source_groundedness": 0.78,
      "hallucination_observed": false,
      "rationale": "Useful disposition axis. Mostly grounded, though labeling the annual-physical (labs ordered) and knee-MRI rows as 'ancillary_referral_only' is a stretch—ordering labs/imaging is not clearly a referral, a mild over-read."
    },
    {
      "name": "preventive_flag",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Flags preventive/screening content, a reasonable axis somewhat overlapping visit_purpose. Well grounded (annual physical->screening; silent rows correctly not_present)."
    }
  ],
  "analytical_usefulness": 0.82,
  "source_groundedness": 0.86,
  "rationale": "The added columns collectively give strong, multi-axis leverage for characterizing patient concerns—clinical_category directly answers the query, while chronicity, visit_purpose, symptom_mechanism, and care_action_type add genuinely different grouping dimensions. body_system is the weakest, being largely redundant with clinical_category. Values are generally sound readings of the source text, with only minor over-reads (referral labels for lab/imaging orders). Silent rows are handled correctly with 'not_present'. No clear hallucinations observed."
}

